namespace RisingLands;
public static class PopulationTests {
 static void Check(bool v,string n){if(!v)throw new Exception("FAIL: "+n);Console.WriteLine("PASS: "+n);}
 public static void Run(string root){
  var s=MissionOneTests.Load(root);var sanctuary=s.World.Buildings.First(b=>b.Type==2&&b.Owner==0);
  var initial=s.Serialize();var free=s.ReleaseResident(sanctuary.Slot);Check(free!=null&&free.Type==9&&free.LegacyState==7,"double-click operation releases exactly one real colonist");
  string released=s.Serialize();var copy=MissionOneTests.Load(root);copy.Restore(released);Check(copy.Serialize()==released,"released colonist and membership survive save/load");
  string hoverState=s.Serialize();Check(s.CanEnterBuilding(free!,sanctuary.Slot)&&s.Serialize()==hoverState,"entry preview validates without changing movement or membership");
  Check(s.CanEnterBuilding(s.World.Units.First(a=>a.Type==5&&a.Owner==0),sanctuary.Slot),"farmer may enter sanctuary to revert into colonist");
  Check(!s.CanEnterBuilding(free!,int.MaxValue),"missing target rejects colonist entry");
  Check(s.EnterBuilding(free!,sanctuary.Slot),"free colonist receives building entry order");for(int i=0;i<10000&&s.ResidentTrips.Count>0;i++)s.Step();Check(s.Residents(sanctuary.Slot)==8,"colonist activates building only on arrival");
  int depot=ResearchTests.Build(s,3,false);var b=s.World.Buildings.First(b=>b.Slot==depot);Check(!s.Inhabited(b)&&s.Residents(depot)==0,"new warehouse is empty and inactive");free=s.ReleaseResident(sanctuary.Slot);Check(free!=null&&s.EnterBuilding(free,depot),"warehouse requires explicit colonist entry");for(int i=0;i<10000&&s.ResidentTrips.Count>0;i++)s.Step();Check(s.Inhabited(b),"explicit warehouse staffing activates it");
  Check(s.ReleaseResident(depot)!=null&&!s.Inhabited(b)&&s.WarehouseSpace()==0,"removing last colonist deactivates warehouse");
  var farmer=s.World.Units.First(a=>a.Type==5&&a.Owner==0);Check(!s.WarehouseSourceAvailable(farmer,b),"uninhabited warehouse cannot withdraw resources");
  free=s.World.Units.First(a=>a.Type==9&&a.LegacyState==7&&a.Route.Count==0);Check(s.EnterBuilding(free,depot),"warehouse can be staffed again");for(int i=0;i<10000&&s.ResidentTrips.Count>0;i++)s.Step();
  var gesture=new ResourceGesture();int drop=Enumerable.Range(0,65536).First(c=>s.Passable(c&255,c>>8)&&s.BuildingAt(c)==null&&s.World.Objects[c]==0);int stock=s.World.Resources[0];
  Check(gesture.Begin(s,new[]{farmer},b.Cell)&&s.World.Resources[0]==stock&&gesture.Commit(s,drop),"Ctrl warehouse-to-ground order validates without early debit");
  farmer.RepeatFood=false;for(int i=0;i<20000&&farmer.Food==0;i++)s.Step();
  int carried=farmer.Food;Check(carried>0,"farmer holds withdrawn cargo before redirection");
  gesture.Cancel();Check(gesture.Redirect(s,new[]{farmer},b.Cell)&&farmer.Food==carried,"loaded farmer can redirect delivery to staffed warehouse");Check(gesture.Redirect(s,new[]{farmer},drop)&&farmer.Food==carried,"loaded farmer redirects cargo without loss");
  Check(gesture.Begin(s,new[]{farmer},5642),"loaded farmer can choose a new collection source");Check(gesture.Commit(s,drop)&&farmer.Food==carried,"loaded two-click collection preserves cargo and confirms new destination");farmer.RepeatFood=false;gesture.Cancel();Check(farmer.Food==carried,"cancelled loaded source gesture preserves cargo");
  for(int i=0;i<20000&&s.World.Objects[drop]!=67;i++)s.Step();Check(s.World.Objects[drop]==67&&s.World.Resources[0]==stock-1,"warehouse pickup debits only withdrawn food and deposits real pile");
  s.Stop(farmer);int crop=ResearchTests.Build(s,4);var culture=s.World.Buildings.First(b=>b.Slot==crop);Check(!s.Inhabited(culture),"new culture is empty and inactive");
  free=s.ReleaseResident(sanctuary.Slot);Check(free!=null&&s.EnterBuilding(free,crop),"player explicitly inhabits culture");for(int i=0;i<10000&&s.ResidentTrips.Count>0;i++)s.Step();
  var fixture=s.OrderPreview();fixture.Stop(fixture.World.Units.First(a=>a.Slot==farmer.Slot));var fc=fixture.Culture(crop);fc.Food=4;fixture.World.Resources[0]-=4;int births=fixture.BornActors.Count;fixture.Step();Check(fixture.BornActors.Count==births,"four foods do not produce baseline colonist");fc.Food++;fixture.World.Resources[0]--;fixture.Step();Check(fixture.BornActors.Count==births+1&&fc.Food==0&&fc.Consumed==5,"fifth food produces colonist next update without provisional timer");
  var supplyFarmer=fixture.World.Units.First(a=>a.Slot==farmer.Slot);fixture.SetFoodDestination(supplyFarmer,2,depot);supplyFarmer.RepeatFood=true;for(int i=0;i<50000&&fixture.World.Resources[0]<20;i++){if(supplyFarmer.FoodJob==0)fixture.GatherNearest(supplyFarmer);fixture.Step();}fixture.Stop(supplyFarmer);Check(fixture.World.Resources[0]>=20,"full crop fixture obtains food through real warehouse deliveries");
  for(int i=0;i<3;i++){fc.Food=5;fixture.World.Resources[0]-=5;fixture.Step();}Check(fixture.Residents(crop)==5,"crop fills its five native housing places");
  var ff=fixture.World.Units.First(a=>a.Slot==farmer.Slot);fixture.Stop(ff);int fullSource=Enumerable.Range(0,65536).Where(c=>WorkerResourceOrders.SourceAvailable(fixture,ff,c)&&fixture.BuildingAt(c)==null).OrderBy(c=>Math.Abs((c&255)-ff.X/1024)+Math.Abs((c>>8)-ff.Y/1024)).First();Check(new ResourceGesture().Begin(fixture,new[]{ff},fullSource),"full crop test can still designate a valid source");var fullGesture=new ResourceGesture();Check(fullGesture.Begin(fixture,new[]{ff},fullSource)&&fullGesture.Commit(fixture,culture.Cell),"food delivery can target full crop");ff.RepeatFood=false;for(int i=0;i<20000&&fixture.Residents(crop)==5;i++)fixture.Step();Check(fixture.Residents(crop)==4&&fixture.World.Units.Any(a=>a.Type==9&&a.LegacyState==7),"food delivery to full crop releases one colonist as original routine does");
  var native=System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(PackageLayout.FromBase("Content/Data/culture_native.json")))!;foreach(var row in native["prices"]!.AsArray())Check(Simulation.CultureFoodCost(row!["level"]!.GetValue<int>())==row["food"]!.GetValue<int>(),"native crop research price level "+row["level"]);
  gesture.Cancel();Check(gesture.Begin(s,new[]{farmer},5642)&&gesture.Commit(s,culture.Cell),"farmer can deliver collected food into culture");
  for(int i=0;i<20000&&farmer.Food==0;i++)s.Step();int cropCargo=farmer.Food;Check(cropCargo>0&&gesture.Redirect(s,new[]{farmer},culture.Cell)&&farmer.Food==cropCargo,"loaded farmer can redirect delivery to crop without food loss");
  farmer.RepeatFood=true;for(int i=0;i<50000&&s.BornActors.Count==0;i++)s.Step();Check(s.BornActors.Count==1&&s.Cultures.Single().Born==1,"staffed culture converts food into new colonist");
  string born=s.Serialize();copy=MissionOneTests.Load(root);copy.Restore(born);Check(copy.Serialize()==born,"generated colonist culture progress and food survive save/load");
  var newborn=s.ReleaseResident(crop);Check(newborn!=null&&s.EnterBuilding(newborn,sanctuary.Slot),"culture colonist can transfer to sanctuary");for(int i=0;i<10000&&s.ResidentTrips.Count>0;i++)s.Step();Check(s.CanRecruit(5,sanctuary.Slot),"staffed sanctuary reports available production");
  var generated=s.ReleaseResident(crop);Check(generated!=null&&generated.Slot==s.BornActors.Single().Slot&&s.EnterBuilding(generated,sanctuary.Slot),"newly generated colonist transfers into sanctuary");for(int i=0;i<10000&&s.ResidentTrips.Count>0;i++)s.Step();
  var members=s.World.BuildingResidents[sanctuary.Slot];members.Remove(generated!.Slot);members.Insert(0,generated.Slot);Check(s.Recruit(5,sanctuary.Slot)&&s.Recruitments.Last().SettlerSlot==generated.Slot,"newly generated colonist can become actual farmer");for(int i=0;i<2000&&s.Recruitments.Any(j=>!j.Finished);i++)s.Step();string trained=s.Serialize();copy=MissionOneTests.Load(root);copy.Restore(trained);Check(copy.Serialize()==trained,"training a generated colonist survives save/load");
  var agricultureWorld=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE03.ETA"));new VisualCatalog().Apply(agricultureWorld);var agricultural=new Simulation(agricultureWorld,new CampaignProgress{StartingLevels=Simulation.UnlockData.Missions.First(m=>m.Mission==3).Levels.ToArray(),SelectedBranch=0});int lab=ResearchTests.PrepareLaboratory(agricultural);Check(agricultural.AssignLaboratoryWorker(lab),"agriculture receives scientist through existing laboratory route");for(int i=0;i<10000&&agricultural.Scientists()==0;i++)agricultural.Step();
  var af=agricultural.World.Units.First(a=>a.Owner==0&&a.Type==5);int harvestBefore=agricultural.WorkerCountdown(af);Check(agricultural.AgricultureResearch.Enabled,"agriculture starts automatically in chosen branch");for(int i=0;i<12600&&agricultural.AgricultureResearch.Completed.Count==0;i++)agricultural.Step();Check(agricultural.AgricultureResearch.Index==3&&agricultural.WorkerCountdown(af)<harvestBefore,"agriculture completion applies native farmer harvest bonus");string agri=agricultural.Serialize();var agricultureCopyWorld=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE03.ETA"));new VisualCatalog().Apply(agricultureCopyWorld);copy=new Simulation(agricultureCopyWorld);copy.Restore(agri);Check(copy.Serialize()==agri,"agriculture progress history and effect survive save/load");
  int food=s.World.Resources[0];s.World.Resources[0]=0;Check(!s.CanRecruit(5,sanctuary.Slot),"missing resources disable production before click");s.World.Resources[0]=(ushort)food;
 }
}
